'use strict';
const el = id => document.getElementById(id);
let csrf = '';
let savedCard = false;
let invitationState = {members:[],credentials:[],invitations:[]};
let vaultItems = [];
let vaultView = 'owned';
let vaultFilter = 'all';
let vaultQuery = '';
let credentialDetail = null;
const fragment = new URLSearchParams(location.hash.slice(1));
if (fragment.has('r') && fragment.has('token')) {
  sessionStorage.setItem('clanker-request',JSON.stringify({id:fragment.get('r'),token:fragment.get('token')}));
  history.replaceState(null,'',location.pathname);
}
let access=null;
try{access=JSON.parse(sessionStorage.getItem('clanker-request') || 'null');}catch{sessionStorage.removeItem('clanker-request');}
async function api(path,data) {
  const response = await fetch(path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(data)});
  const result = await response.json();
  if (!response.ok) { const error = new Error(result.error || 'Please try again.');error.status=response.status;throw error; }
  return result;
}
function fail(error) {el('error').textContent=error.message;el('error').hidden=false;}
function showConfirmation(result, kind) {
  el('form').reset();el('phone-form').reset();el('code-form').reset();el('api-key-form').reset();
  el('payment-form').reset();el('card-number').type='password';el('card-cvc').type='password';
  for(const [id,label] of [['reveal-card-number','card number'],['reveal-card-cvc','CVV']]){el(id).textContent='Show';el(id).setAttribute('aria-label','Show '+label);}
  el('password').type='password';el('reveal').textContent='Show';el('reveal').setAttribute('aria-label','Show password');
  el('api-key').type='password';el('reveal-api-key').textContent='Show';el('reveal-api-key').setAttribute('aria-label','Show API key');
  sessionStorage.removeItem('clanker-request');access=null;
  el('request-header').hidden=true;el('form').hidden=true;el('code-form').hidden=true;el('api-key-form').hidden=true;el('signin').hidden=true;el('error').hidden=true;
  el('payment-form').hidden=true;
  el('phone-form').hidden=true;
  // The live gateway may serve the new assets before its handlers are reloaded.
  el('return-slack').href=result.return_slack_url || 'slack://open';
  const code=kind==='code',payment=kind==='payment'||kind==='declined';
  el('confirmation-subject').textContent=payment?'Purchase':code?'Verification':'Vault';
  el('confirmation-action').textContent=payment?(kind==='declined'?'declined':'approved'):code?'submitted':'updated';
  const saved={login:'Your login is saved.',sms:'Your phone number is saved. Clanker will request a fresh SMS code through a private form.',api_key:'Your API key is saved.',code:'Your code is submitted.'};
  el('confirmation-description').textContent=payment?(kind==='declined'?'This purchase was cancelled. Your card was not used.':'Clanker will continue this approved purchase automatically. Payment is confirmed only after checking the merchant receipt.') : kind==='sms'?saved.sms:saved[kind]+' Clanker will continue your task automatically.';
  document.title=payment?'Purchase '+(kind==='declined'?'declined':'approved')+' · clanker':code?'Verification submitted · clanker':'Vault updated · clanker';
  document.body.classList.add('completed');el('confirmation').hidden=false;el('confirmation').focus();
}
el('reveal').onclick=()=>{const input=el('password');input.type=input.type==='password'?'text':'password';el('reveal').textContent=input.type==='password'?'Show':'Hide';el('reveal').setAttribute('aria-label',input.type==='password'?'Show password':'REDACTED');};
el('reveal-api-key').onclick=()=>{const input=el('api-key');input.type=input.type==='password'?'text':'password';el('reveal-api-key').textContent=input.type==='password'?'Show':'Hide';el('reveal-api-key').setAttribute('aria-label',input.type==='password'?'Show API key':'Hide API key');};
for(const [inputId,buttonId,label] of [['card-number','reveal-card-number','card number'],['card-cvc','reveal-card-cvc','CVV']]){el(buttonId).onclick=()=>{const input=el(inputId);input.type=input.type==='password'?'text':'password';el(buttonId).textContent=input.type==='password'?'Show':'Hide';el(buttonId).setAttribute('aria-label',(input.type==='password'?'Show ':'Hide ')+label);};}
el('payment-form').onsubmit=async event=>{event.preventDefault();el('error').hidden=true;el('save-payment').disabled=true;el('decline-payment').disabled=true;
  const fields={approved:el('approve-payment').checked,cvc:el('card-cvc').value};
  if(!savedCard)Object.assign(fields,{card_number:el('card-number').value,exp_month:el('card-month').value,exp_year:el('card-year').value,cardholder_name:el('card-name').value});
  try{const result=await api('/api/payment',{...access,fields});showConfirmation(result,'payment');}
  catch(error){fail(error);}finally{el('save-payment').disabled=false;el('decline-payment').disabled=false;}
};
el('decline-payment').onclick=async()=>{el('save-payment').disabled=true;el('decline-payment').disabled=true;
  try{await api('/api/payment/decline',access);showConfirmation({},'declined');}
  catch(error){fail(error);}finally{el('save-payment').disabled=false;el('decline-payment').disabled=false;}
};
el('signin').onclick=async()=>{try{el('signin').disabled=true;const result=await api('/auth/start',location.pathname==='/vault'?{}:access);location.assign(result.url);}catch(error){fail(error);el('signin').disabled=false;}};
el('form').onsubmit=async event=>{event.preventDefault();el('error').hidden=true;el('save').disabled=true;
  try{const result=await api('/api/save',{...access,fields:{identifier:el('identifier').value,password:el('password').value,otp_secret:el('otp').value}});
    showConfirmation(result,'login');
  }catch(error){fail(error);}finally{el('save').disabled=false;}
};
el('code-form').onsubmit=async event=>{event.preventDefault();el('error').hidden=true;el('submit-code').disabled=true;
  try{const result=await api('/api/code',{...access,fields:{code:el('code').value}});showConfirmation(result,'code');
  }catch(error){fail(error);}finally{el('submit-code').disabled=false;}
};
el('phone-form').onsubmit=async event=>{event.preventDefault();el('error').hidden=true;el('save-phone').disabled=true;
  try{const result=await api('/api/save',{...access,fields:{phone_number:el('phone-number').value}});showConfirmation(result,'sms');}
  catch(error){fail(error);}finally{el('save-phone').disabled=false;}
};
el('api-key-form').onsubmit=async event=>{event.preventDefault();el('error').hidden=true;el('save-api-key').disabled=true;
  try{const result=await api('/api/api-key',{...access,fields:{api_key:el('api-key').value}});showConfirmation(result,'api_key');
  }catch(error){fail(error);}finally{el('save-api-key').disabled=false;}
};
el('close-invite').onclick=()=>el('invite-dialog').close();
el('invite-vault').onclick=()=>openInvitations();
el('invite-member').onchange=()=>{el('invite-consent').checked=false;renderCredentialSelection();};
function selectedCredentials(){return [...el('credential-selection').querySelectorAll('input:checked')].map(input=>input.value);}
function updateInviteSelection(){
  const selected=selectedCredentials();
  el('send-invite').disabled=!el('invite-member').value||!selected.length;
  el('invite-card-note').hidden=!invitationState.credentials.some(item=>selected.includes(item.id)&&item.kind==='payment');
}
function renderCredentialSelection(){
  const recipient=el('invite-member').value;
  const active=invitationState.invitations.filter(invitation=>invitation.recipient===recipient&&invitation.revoked==null);
  const handles=new Set(active.map(invitation=>invitation.handle));
  el('invite-title').textContent=active.length?'Manage vault access':'Invite to vault';
  el('send-invite').textContent=active.length?'Save access':'Invite';
  el('credential-selection').replaceChildren();
  for(const item of invitationState.credentials){
    const label=document.createElement('label');label.className='credential-option';
    const input=document.createElement('input');input.type='checkbox';input.value=item.id;input.checked=handles.has(item.id);input.disabled=!recipient;
    input.onchange=()=>{el('invite-consent').checked=false;updateInviteSelection();};
    const text=document.createElement('span'),title=document.createElement('strong'),detail=document.createElement('small');
    title.textContent=item.label;
    const kind=item.kind==='api_key'?'API key':item.kind==='payment'?'Payment card':'Login';
    detail.textContent=[kind,item.origin,item.identifier].filter(Boolean).join(' · ');
    text.append(title,detail);label.append(input,text);el('credential-selection').append(label);
  }
  if(!invitationState.credentials.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='Save a credential in your vault before inviting someone.';el('credential-selection').append(empty);}
  updateInviteSelection();
}
async function removeMemberAccess(recipient,name){
  if(!confirm('Remove '+name+'’s access to your vault? Any affected private browser sessions will be closed.'))return;
  try{const result=await api('/api/invite',{recipient,handles:[]});await refreshInvitations();
    el('vault-message').textContent=result.cleanup_pending?'Access removed. Browser cleanup is pending; further browser tasks for this member are blocked.':'Access removed.';el('vault-message').hidden=false;
  }catch(error){fail(error);}
}
async function refreshInvitations(){
  const result=await api('/api/invitations',{handle:null});csrf=result.csrf;invitationState=result;
  const selectedMember=el('invite-member').value;
  el('invite-member').replaceChildren(new Option('Choose a member',''));
  const names=new Map(result.members.map(member=>[member.id,member.name]));
  for(const member of result.members){
    const duplicate=result.members.filter(other=>other.name===member.name).length>1;
    const option=new Option(member.name+(duplicate?' · '+member.id.slice(-6):''),member.id);
    el('invite-member').append(option);
  }
  el('invite-member').value=selectedMember;
  el('invite-vault').disabled=!result.credentials.length||!result.members.length;
  renderCredentialSelection();
  renderInvitationList();
  renderDashboard();
}
function renderInvitationList(){
  const result=invitationState;
  const names=new Map(result.members.map(member=>[member.id,member.name]));
  el('invitation-list').replaceChildren();
  if(!result.invitations.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='No one else has access to your vault.';el('invitation-list').append(empty);}
  const groups=new Map();
  for(const invitation of result.invitations){if(!groups.has(invitation.recipient))groups.set(invitation.recipient,[]);groups.get(invitation.recipient).push(invitation);}
  for(const [recipient,invitations] of groups){
    const row=document.createElement('div');row.className='invitation-row';
    const name=names.get(recipient)||'Slack member '+recipient;
    const active=invitations.filter(invitation=>invitation.revoked==null),pending=invitations.find(invitation=>invitation.cleanup_pending);
    if(!active.length&&!pending)continue;
    const label=document.createElement('span'),title=document.createElement('strong'),detail=document.createElement('small');
    title.textContent=name;detail.textContent=active.length?active.length+' '+(active.length===1?'credential':'credentials')+' · '+active.map(invitation=>invitation.credential).join(', '):'Access removed';
    label.append(title,detail);
    if(pending){const warning=document.createElement('small');warning.textContent='Browser cleanup pending';label.append(warning);}
    const actions=document.createElement('div');actions.className='sharing-actions';
    if(active.length&&names.has(recipient)){const edit=document.createElement('button');edit.type='button';edit.textContent='Edit access';edit.onclick=()=>openInvitations(recipient);actions.append(edit);}
    if(active.length){const remove=document.createElement('button');remove.type='button';remove.textContent='Remove';remove.onclick=()=>removeMemberAccess(recipient,name);actions.append(remove);}
    if(pending){const retry=document.createElement('button');retry.type='button';retry.textContent='Retry cleanup';retry.onclick=async()=>{
      retry.disabled=true;try{const status=await api('/api/invite/revoke',{id:pending.id});await refreshInvitations();el('vault-message').textContent=status.cleanup_pending?'Browser cleanup is still pending. Further browser tasks for this member remain blocked.':'Browser cleanup complete.';el('vault-message').hidden=false;}catch(error){fail(error);retry.disabled=false;}
    };actions.append(retry);}
    row.append(make('span','vault-avatar',initials(name)),label,actions);el('invitation-list').append(row);
  }
}
async function openInvitations(recipient=''){
  el('invite-form').reset();el('invite-error').hidden=true;el('send-invite').disabled=true;
  el('invite-member').value=recipient;renderCredentialSelection();
  el('invite-dialog').showModal();
  try{await refreshInvitations();}catch(error){el('invite-error').textContent=error.message;el('invite-error').hidden=false;el('send-invite').disabled=true;}
}
el('invite-form').onsubmit=async event=>{
  event.preventDefault();const recipient=el('invite-member').value,handles=selectedCredentials();if(!recipient||!handles.length||!el('invite-consent').checked)return;
  el('send-invite').disabled=true;el('invite-error').hidden=true;
  try{const result=await api('/api/invite',{handles,recipient});await refreshInvitations();el('invite-dialog').close();
    const message=[result.cleanup_pending?'Access updated. Browser cleanup is pending; further browser tasks for this member are blocked.':'Vault access saved. This member can use the selected credentials.'];
    if(result.notification==='sent')message.push('They have been notified in Slack.');
    if(result.notification==='failed')message.push('The Slack notification could not be confirmed. Let this member know directly.');
    el('vault-message').textContent=message.join(' ');el('vault-message').hidden=false;
  }catch(error){el('invite-error').textContent=error.message;el('invite-error').hidden=false;updateInviteSelection();}
};
let personalKind='';
let personalState={};
const personalFields={name:{given_name:'personal-given-name',middle_name:'personal-middle-name',family_name:'personal-family-name'},dob:{date_of_birth:'personal-dob'},gender:{gender:'personal-gender'},email:{email:'personal-email'},phone:{phone_number:'personal-phone',country_code:'personal-country-code'},address:{address_line1:'personal-line1',address_line2:'personal-line2',city:'personal-city',state:'personal-state',postal_code:'personal-postal',country:'personal-country'}};
const personalLabels={name:'name',dob:'date of birth',gender:'gender',email:'primary email',phone:'primary phone',address:'primary address'};
function renderPersonalInfo(info){
  personalState=info||{};el('personal-list').replaceChildren();
  for(const button of el('personal-add').querySelectorAll('[data-add-personal]'))button.hidden=!Object.hasOwn(personalState,button.dataset.addPersonal);
  const saved=Object.entries(personalState).filter(([,item])=>item.saved);
  if(!saved.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='No personal info saved';el('personal-list').append(empty);}
  for(const [kind,item] of saved){
    const row=document.createElement('article');row.className='personal-row';
    const text=document.createElement('div'),label=document.createElement('strong'),detail=document.createElement('small');
    label.textContent=item.label;detail.textContent=item.summary;text.append(label,detail);
    const edit=document.createElement('button');edit.type='button';edit.textContent='Edit';edit.setAttribute('aria-label','Edit '+personalLabels[kind]);edit.onclick=()=>openPersonal(kind);
    row.append(text,edit);el('personal-list').append(row);
  }
}
function clearPersonalForm(){el('personal-form').reset();for(const fields of Object.values(personalFields))for(const id of Object.values(fields))el(id).value='';}
async function openPersonal(kind){
  if(window.kernelVault){try{const result=await api('/api/personal/details',{kind});window.location.assign(result.collection_url);}catch(error){fail(error);}return;}
  personalKind=kind;clearPersonalForm();el('personal-add').open=false;el('personal-error').hidden=true;
  const editing=Boolean(personalState[kind]?.saved);el('personal-title').textContent=(editing?'Edit ':'Add ')+personalLabels[kind];
  for(const key of Object.keys(personalFields)){
    el('personal-'+key+'-fields').hidden=key!==kind;
    for(const [field,id] of Object.entries(personalFields[key]))el(id).required=key===kind&&!['middle_name','family_name','address_line2','state','country_code'].includes(field);
  }
  if(kind==='dob'){const today=new Date();el('personal-dob').max=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');}
  el('remove-personal').hidden=!editing;el('save-personal').disabled=editing;el('personal-dialog').showModal();
  if(editing){try{const result=await api('/api/personal/details',{kind});for(const [field,id] of Object.entries(personalFields[kind]))el(id).value=result.fields[field]||'';}
    catch(error){el('personal-error').textContent=error.message;el('personal-error').hidden=false;return;}}
  el('save-personal').disabled=false;el(Object.values(personalFields[kind])[0]).focus();
}
for(const button of document.querySelectorAll('[data-add-personal]'))button.onclick=()=>openPersonal(button.dataset.addPersonal);
el('close-personal').onclick=()=>el('personal-dialog').close();
el('personal-dialog').addEventListener('close',clearPersonalForm);
el('personal-form').onsubmit=async event=>{
  event.preventDefault();el('save-personal').disabled=true;el('personal-error').hidden=true;
  const fields={};for(const [field,id] of Object.entries(personalFields[personalKind]))fields[field]=el(id).value;
  try{const result=await api('/api/personal/save',{kind:personalKind,fields});renderPersonalInfo(result.personal_info);el('personal-dialog').close();
    el('vault-message').textContent='Your '+personalLabels[personalKind]+' is saved for repeat use.';el('vault-message').hidden=false;}
  catch(error){el('personal-error').textContent=error.message;el('personal-error').hidden=false;}finally{el('save-personal').disabled=false;}
};
el('remove-personal').onclick=async()=>{
  if(!confirm('Remove your '+personalLabels[personalKind]+'? Existing website logins keep their own saved details.'))return;
  el('remove-personal').disabled=true;
  try{const result=await api('/api/personal/remove',{kind:personalKind});renderPersonalInfo(result.personal_info);el('personal-dialog').close();}
  catch(error){el('personal-error').textContent=error.message;el('personal-error').hidden=false;}finally{el('remove-personal').disabled=false;}
};
function make(tag,className='',text=''){
  const node=document.createElement(tag);node.className=className;node.textContent=text;return node;
}
function initials(name){return String(name||'').trim().split(/\s+/).slice(0,2).map(word=>word[0]||'').join('').toUpperCase();}
function vaultIcon(name){
  const paths={search:['M21 21l-4.4-4.4','M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0'],login:['M7 11V7a5 5 0 0 1 10 0v4','M5 11h14v10H5z','M12 15v2'],api_key:['M15 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0','M10 11v10','M10 17h4','M10 21h4'],payment:['M2 5h20v14H2z','M2 9h20','M6 15h3'],invite:['M15 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0','M3 21v-2a6 6 0 0 1 12 0v2','M20 11v6','M17 14h6']};
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
  for(const [key,value] of Object.entries({viewBox:'0 0 24 24',fill:'none',stroke:'currentColor','stroke-width':'1.6','stroke-linecap':'round','stroke-linejoin':'round','aria-hidden':'true'}))svg.setAttribute(key,value);
  for(const d of paths[name]||paths.login){const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',d);svg.append(path);}
  return svg;
}
function credentialKind(item){return item.kind==='api_key'?'API key':item.kind==='payment'?'Card':'Login';}
function sharedBy(item){return invitationState.members.find(member=>member.id===item.shared_by)?.name||item.shared_by||'another Slack member';}
function credentialAccess(item){
  if(item.access==='invited')return 'From '+sharedBy(item);
  const recipients=new Set(invitationState.invitations.filter(grant=>grant.handle===item.id&&grant.revoked==null).map(grant=>grant.recipient));
  return recipients.size?'Shared with '+recipients.size:'Only you';
}
function renderVaultItems(items){vaultItems=items;renderDashboard();}
function renderDashboard(){
  const owned=vaultItems.filter(item=>item.access!=='invited'),shared=vaultItems.filter(item=>item.access==='invited');
  const people=new Set(invitationState.invitations.filter(grant=>grant.revoked==null).map(grant=>grant.recipient));
  el('count-owned').textContent=owned.length;el('count-shared').textContent=shared.length;el('count-people').textContent=people.size;
  el('vault-actions').hidden=!owned.length;
  for(const tab of el('vault-tabs').querySelectorAll('[data-view]')){const active=tab.dataset.view===vaultView;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;}

